"""exp-003: per-subroutine Toffoli accounting of the official sample dqi circuit.

Self-contained private Kaggle script kernel (generated by build_kernel.py, which inlines
src/kmx_tag_count.py as COUNTER_SRC). It never calls any Kaggle API and never submits.

Steps (each in its own child process, memory sampled by the parent):
  sample_count  load sample dqi.kmb, record stats + canonical sha256, dump .kmx, run the tag counter
  gen_compare   build dqi_reference_circuit.build_reference_circuit(4095, 70, 12) with kickmix 1.0.0,
                compare to the sample (==, canonical sha256, op counts), run the tag counter on it
  dqi_salt_*    unmodified official verifier on the sample, --salt exp003-a / -b / -c
"""
from __future__ import annotations

import argparse
import hashlib
import io
import json
import os
import platform
import subprocess
import sys
import threading
import time
from pathlib import Path

ON_KAGGLE = Path('/kaggle/working').is_dir()
POLL_S = 0.5
KICKMIX_PIN = 'kickmix==1.0.0'
SALTS = ['exp003-a', 'exp003-b', 'exp003-c']
OUT = Path(os.environ.get('EXP003_OUT') or ('/kaggle/working/exp003' if ON_KAGGLE else 'exp003_local_out')).resolve()
TMP = Path(os.environ.get('EXP003_TMP') or ('/tmp/exp003' if ON_KAGGLE else 'exp003_local_tmp')).resolve()

COUNTER_SRC = '"""Streaming per-subroutine Toffoli accounting for kickmix .kmx text circuits.\n\nReads a .kmx file line by line (constant memory apart from the tallies) and\nattributes every Toffoli-like gate (CCX, CCZ, CSWAP) to the stack of\n`INFO_TAG "@enter:<name>"` / `"@exit:<name>"` marks that encloses it. kickmix\nemits such marks for its own arithmetic (gf_mul, c_gf_mul, gf_inverse_chain,\ngf_div, ...) and `CircuitBuilder.mark(...)` emits them for user code.\n\nIt also tracks the classical condition stack (`PUSH_CONDITION if bK` /\n`POP_CONDITION`, plus inline `... if bK`) so that conditioned Toffolis can be\nreported separately, together with how each condition bit was last defined\n(the BIT_STORE1 sources since its last BIT_STORE0, or an HMR measurement).\nThat is what is needed to turn static counts into expected per-shot counts.\n\nUsage:\n    python src/kmx_tag_count.py circuit.kmx out.json\n"""\n\nfrom __future__ import annotations\n\nimport collections\nimport json\nimport sys\n\nTOFFOLI_LIKE = {\'CCX\': 3, \'CCZ\': 3, \'CSWAP\': 3}\n\n\ndef count(path: str) -> dict:\n    stack: list[str] = []          # open tag names\n    inst_tof: list[int] = []       # inclusive Toffoli count of each open tag instance\n    cond_stack: list[str] = []     # condition bits currently pushed\n    by_path = collections.Counter()            # full path -> Toffolis\n    by_path_cond = collections.Counter()       # (full path, cond tuple) -> Toffolis\n    inst_hist = collections.defaultdict(collections.Counter)  # tag -> {inclusive tof: n instances}\n    bit_def: dict[str, tuple] = {}             # bit -> definition\n    push_defs = collections.Counter()          # definition shape at each PUSH -> n pushes\n    cur_def: list[tuple] = []                  # definition of each pushed condition\n    reg_bits: dict[str, str] = {}              # bit -> \'Ename[idx]\'\n    reg_members = collections.defaultdict(list)\n    pending_reg: dict[str, list] = collections.defaultdict(list)\n    op_counts = collections.Counter()\n\n    def describe(d: tuple) -> dict:\n        # Shape of a condition-bit definition: which registers feed the OR, and\n        # how many bits of each (register names collapsed to their letter prefix).\n        if d[0] != \'or_of\':\n            return {\'kind\': d[0]}\n        regs = collections.Counter(reg_bits.get(b, b).split(\'[\')[0] for b in d[1])\n        prefixes = collections.Counter(\'\'.join(ch for ch in r if not ch.isdigit()) for r in regs)\n        return {\'kind\': \'or_of\', \'n_sources\': len(d[1]), \'n_registers\': len(regs),\n                \'bits_per_register\': sorted(set(regs.values())),\n                \'register_prefixes\': dict(prefixes)}\n\n    total_tof = 0\n    cond_tof = 0\n    n_lines = 0\n\n    with open(path, \'r\', encoding=\'utf-8\') as f:\n        for line in f:\n            n_lines += 1\n            if not line or line[0] == \'#\':\n                continue\n            parts = line.split()\n            if not parts:\n                continue\n            op = parts[0]\n            op_counts[op] += 1\n            if op == \'INFO_TAG\':\n                tag = line.split(\'"\', 2)[1]\n                if tag.startswith(\'@enter:\'):\n                    stack.append(tag[7:])\n                    inst_tof.append(0)\n                elif tag.startswith(\'@exit:\'):\n                    name = tag[6:]\n                    if not stack or stack[-1] != name:\n                        raise ValueError(f\'line {n_lines}: exit {name} does not match {stack[-1:]}\')\n                    stack.pop()\n                    t = inst_tof.pop()\n                    inst_hist[name][t] += 1\n                continue\n            if op in TOFFOLI_LIKE:\n                args = parts[1:]\n                inline = None\n                if \'if\' in args:\n                    k = args.index(\'if\')\n                    inline = args[k + 1:]\n                    args = args[:k]\n                n = len(args) // TOFFOLI_LIKE[op]\n                total_tof += n\n                for i in range(len(inst_tof)):\n                    inst_tof[i] += n\n                key = \'/\'.join(stack)\n                by_path[key] += n\n                conds = tuple(cond_stack) + (tuple(inline) if inline else ())\n                if conds:\n                    cond_tof += n\n                    sig = json.dumps([describe(d) for d in cur_def]\n                                     + [{\'kind\': \'inline\', \'bits\': inline}] * bool(inline),\n                                     sort_keys=True)\n                    by_path_cond[(key, sig)] += n\n                continue\n            if op == \'PUSH_CONDITION\':\n                bit = parts[2]\n                cond_stack.append(bit)\n                d = bit_def.get(bit, (\'undefined\',))\n                cur_def.append(d)\n                push_defs[json.dumps(describe(d), sort_keys=True)] += 1\n                continue\n            if op == \'POP_CONDITION\':\n                cond_stack.pop()\n                cur_def.pop()\n                continue\n            if op == \'BIT_STORE0\':\n                for b in parts[1:]:\n                    if b == \'if\':\n                        break\n                    bit_def[b] = (\'store0\',)\n                continue\n            if op == \'BIT_STORE1\':\n                if \'if\' in parts:\n                    k = parts.index(\'if\')\n                    tgts, srcs = parts[1:k], parts[k + 1:]\n                else:\n                    tgts, srcs = parts[1:], []\n                for b in tgts:\n                    prev = bit_def.get(b, (\'store0\',))\n                    if prev[0] == \'or_of\':\n                        bit_def[b] = (\'or_of\', prev[1] + tuple(srcs))\n                    elif srcs:\n                        bit_def[b] = (\'or_of\', tuple(srcs))\n                    else:\n                        bit_def[b] = (\'store1\',)\n                continue\n            if op == \'HMR\':\n                # HMR q b: X-basis measurement into bit b (random outcome).\n                for b in parts[1:]:\n                    if b.startswith(\'b\'):\n                        bit_def[b] = (\'measured\',)\n                continue\n            if op == \'APPEND_TO_REGISTER\':\n                pending_reg[parts[2]].append(parts[1])\n                continue\n            if op == \'REGISTER\':\n                rid = parts[1]\n                name = line.split(\'"\')[1] if \'"\' in line else rid\n                for i, b in enumerate(pending_reg.get(rid, [])):\n                    reg_bits[b] = f\'{name}[{i}]\'\n                continue\n\n    if stack:\n        raise ValueError(f\'unclosed tags at EOF: {stack}\')\n\n    cond_summary = collections.defaultdict(lambda: {\'toffolis\': 0, \'definitions\': collections.Counter()})\n    for (key, sig), n in by_path_cond.items():\n        top = key.split(\'/\')[0] if key else \'\'\n        cond_summary[top][\'toffolis\'] += n\n        cond_summary[top][\'definitions\'][sig] += n\n\n    return {\n        \'file\': path,\n        \'n_lines\': n_lines,\n        \'total_toffoli_like\': total_tof,\n        \'conditioned_toffoli_like\': cond_tof,\n        \'op_counts\': dict(op_counts),\n        \'by_path\': dict(sorted(by_path.items(), key=lambda kv: -kv[1])),\n        \'instance_histograms\': {k: {str(t): c for t, c in sorted(v.items())}\n                                for k, v in sorted(inst_hist.items())},\n        \'conditioned_by_top_mark\': {k: {\'toffolis\': v[\'toffolis\'],\n                                        \'definitions\': dict(v[\'definitions\'])}\n                                    for k, v in cond_summary.items()},\n        \'push_condition_definitions\': dict(push_defs),\n        \'conditioned_by_path\': {f\'{k} | {c}\': n for (k, c), n in\n                                sorted(by_path_cond.items(), key=lambda kv: -kv[1])[:200]},\n    }\n\n\ndef main() -> None:\n    res = count(sys.argv[1])\n    with open(sys.argv[2], \'w\') as f:\n        json.dump(res, f, indent=1)\n    print(json.dumps({k: res[k] for k in (\'n_lines\', \'total_toffoli_like\',\n                                          \'conditioned_toffoli_like\')}))\n\n\nif __name__ == \'__main__\':\n    main()\n'


def find_data_root() -> Path:
    marker = Path('verifiers') / 'dqi' / 'verify_submission_dqi.py'
    for dirpath, dirnames, _ in os.walk('/kaggle/input'):
        if (Path(dirpath) / marker).is_file():
            return Path(dirpath)
        if dirpath.count(os.sep) > 6:
            dirnames[:] = []
    raise FileNotFoundError('competition data not found under /kaggle/input')


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 22), b''):
            h.update(chunk)
    return h.hexdigest()


def canonical_sha(circuit) -> str:
    # Same method as verify_submission_dqi.py _circuit_sha256.
    buf = io.BytesIO()
    circuit.to_file(buf, format='kmb')
    return hashlib.sha256(buf.getvalue()).hexdigest()


def load_counter():
    import types
    mod = types.ModuleType('kmx_tag_count')
    exec(compile(COUNTER_SRC, 'kmx_tag_count.py', 'exec'), mod.__dict__)
    return mod


def stats_dict(circuit) -> dict:
    s = circuit.operation_statistics()
    return {'num_qubits': circuit.num_qubits, 'num_bits': circuit.num_bits,
            'num_toffoli_like': s.num_toffoli_like, 'num_t_like': s.num_t_like,
            'num_instructions': s.num_instructions, 'op_counts': dict(s)}


def tag_count(circuit, name: str) -> dict:
    counter = load_counter()
    TMP.mkdir(parents=True, exist_ok=True)
    kmx = TMP / f'{name}.kmx'
    t0 = time.time()
    circuit.to_file(str(kmx), format='kmx')
    t1 = time.time()
    size = kmx.stat().st_size
    res = counter.count(str(kmx))
    t2 = time.time()
    kmx.unlink()
    res['kmx_bytes'] = size
    res['kmx_write_s'] = round(t1 - t0, 1)
    res['count_s'] = round(t2 - t1, 1)
    return res


def step_sample_count(data: Path) -> None:
    import kickmix as km
    path = data / 'sample_submission' / 'dqi.kmb'
    t0 = time.time()
    c = km.Circuit.from_file(str(path))
    info = {'file_sha256': sha256_file(path), 'load_s': round(time.time() - t0, 1),
            'canonical_sha256': canonical_sha(c), **stats_dict(c)}
    res = tag_count(c, 'sample')
    assert res['total_toffoli_like'] == info['num_toffoli_like'], (res['total_toffoli_like'], info)
    res['circuit_info'] = info
    (OUT / 'sample_count.json').write_text(json.dumps(res, indent=1))
    print(json.dumps({'sample': info['num_toffoli_like'], 'q': info['num_qubits'],
                      'tag_total': res['total_toffoli_like'],
                      'conditioned': res['conditioned_toffoli_like']}))


def step_gen_compare(data: Path) -> None:
    import kickmix as km
    sys.path.insert(0, str(data / 'verifiers' / 'dqi'))
    import dqi_reference_circuit as ref
    t0 = time.time()
    mnb = [int(x) for x in os.environ.get('EXP003_MNB', '4095,70,12').split(',')]  # smoke-test override
    g = ref.build_reference_circuit(*mnb)
    build_s = time.time() - t0
    ginfo = {'build_s': round(build_s, 1), 'canonical_sha256': canonical_sha(g), **stats_dict(g)}
    s = km.Circuit.from_file(str(data / 'sample_submission' / 'dqi.kmb'))
    sinfo = {'canonical_sha256': canonical_sha(s), **stats_dict(s)}
    equal = bool(g == s)
    del s
    res = tag_count(g, 'generator')
    assert res['total_toffoli_like'] == ginfo['num_toffoli_like']
    out = {'generator': ginfo, 'sample': sinfo, 'circuit_equal': equal,
           'canonical_sha_equal': ginfo['canonical_sha256'] == sinfo['canonical_sha256'],
           'op_counts_equal': ginfo['op_counts'] == sinfo['op_counts'],
           'generator_source_sha256': sha256_file(data / 'verifiers' / 'dqi' / 'dqi_reference_circuit.py')}
    (OUT / 'gen_compare.json').write_text(json.dumps(out, indent=1))
    (OUT / 'generator_count.json').write_text(json.dumps(res, indent=1))
    print(json.dumps({k: out[k] for k in ('circuit_equal', 'canonical_sha_equal', 'op_counts_equal')}))


def proc_hwm(p) -> int:
    try:
        with open(f'/proc/{p.pid}/status') as f:
            for line in f:
                if line.startswith('VmHWM:'):
                    return int(line.split()[1]) * 1024
    except OSError:
        pass
    try:
        return int(getattr(p.memory_info(), 'peak_wset', 0) or 0)
    except Exception:
        return 0


def run_child(label: str, cmd: list[str]) -> dict:
    import psutil
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', PYTHONUNBUFFERED='1',
               EXP003_OUT=str(OUT), EXP003_TMP=str(TMP))
    so, se = OUT / f'{label}.stdout.txt', OUT / f'{label}.stderr.log'
    peaks = {'tree_rss_peak_bytes': 0, 'proc_hwm_peak_bytes': 0, 'sys_used_peak_bytes': 0}
    t0 = time.time()
    with open(so, 'wb') as fo, open(se, 'wb') as fe:
        child = subprocess.Popen(cmd, stdout=fo, stderr=fe, env=env, cwd=str(OUT))
        root = psutil.Process(child.pid)
        stop = threading.Event()

        def poll() -> None:
            while not stop.is_set():
                try:
                    procs = [root] + root.children(recursive=True)
                except psutil.Error:
                    procs = []
                rss = 0
                for p in procs:
                    try:
                        rss += p.memory_info().rss
                    except psutil.Error:
                        pass
                    peaks['proc_hwm_peak_bytes'] = max(peaks['proc_hwm_peak_bytes'], proc_hwm(p))
                peaks['tree_rss_peak_bytes'] = max(peaks['tree_rss_peak_bytes'], rss)
                peaks['sys_used_peak_bytes'] = max(peaks['sys_used_peak_bytes'],
                                                   psutil.virtual_memory().used)
                stop.wait(POLL_S)

        th = threading.Thread(target=poll, daemon=True)
        th.start()
        rc = child.wait()
        stop.set()
        th.join()
    text = so.read_text(errors='replace')
    parsed = None
    if '{' in text:
        try:
            parsed = json.loads(text[text.index('{'):])
        except ValueError:
            parsed = None
    rec = {'label': label, 'cmd': cmd, 'returncode': rc, 'wall_s': round(time.time() - t0, 1),
           **peaks, 'output': parsed}
    print(json.dumps({k: rec[k] for k in ('label', 'returncode', 'wall_s', 'proc_hwm_peak_bytes')}),
          flush=True)
    return rec


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument('--step', default=None)
    ap.add_argument('--data-root', type=Path, default=None)
    ap.add_argument('--skip-verify', action='store_true')
    args = ap.parse_args()
    data = (args.data_root or find_data_root()).resolve()
    OUT.mkdir(parents=True, exist_ok=True)
    if args.step == 'sample_count':
        return step_sample_count(data)
    if args.step == 'gen_compare':
        return step_gen_compare(data)

    if ON_KAGGLE:
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', KICKMIX_PIN], check=True)
    from importlib.metadata import version
    info = {'platform': platform.platform(), 'python': sys.version, 'cpu_count': os.cpu_count(),
            'kickmix': version('kickmix'), 'numpy': version('numpy'), 'data_root': str(data),
            'verifier_sha256': sha256_file(data / 'verifiers' / 'dqi' / 'verify_submission_dqi.py'),
            'sample_dqi_sha256': sha256_file(data / 'sample_submission' / 'dqi.kmb')}
    me = str(Path(__file__).resolve())
    runs = [run_child('sample_count', [sys.executable, me, '--step', 'sample_count',
                                       '--data-root', str(data)]),
            run_child('gen_compare', [sys.executable, me, '--step', 'gen_compare',
                                      '--data-root', str(data)])]
    if not args.skip_verify:
        verifier = str(data / 'verifiers' / 'dqi' / 'verify_submission_dqi.py')
        sample = str(data / 'sample_submission' / 'dqi.kmb')
        for salt in SALTS:
            runs.append(run_child(f'dqi_salt_{salt}',
                                  [sys.executable, verifier, sample, '--salt', salt]))
    (OUT / 'runs.json').write_text(json.dumps({'machine': info, 'runs': runs}, indent=1))
    print('done', flush=True)


if __name__ == '__main__':
    main()
